describe('Product Detail Page Navigation', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com/');
  });

  it('should navigate to product detail page and return to catalogue successfully', () => {
    // Login with standard user credentials
    cy.get('#user-name').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    // Verify login success and navigate to product page
    cy.url().should('include', '/inventory.item');
    cy.get('[data-test="title"]').should('contain', 'Products');

    // Click on the first product to navigate to detail page
    cy.get('[data-test="inventory-item-name"]').first().click();

    // Verify navigation to product detail page
    cy.url().should('include', '/inventory-item');
    cy.get('[data-testid="inventory-item-title"]').should('be.visible');
    cy.get('[data-test="inventory-item-name"]').should('contain', 'Sauce Labs Backpack');

    // Click the back button to return to catalogue
    cy.get('[data-testid="back-to-products"]').click();

    // Verify return to catalogue page
    cy.url().should('include', '/inventory.item');
    cy.get('[data-test="title"]').should('contain', 'Products');
    cy.get('[data-test="inventory-list"]').should('be.visible');
  });

  it('should handle navigation when product detail page is not found', () => {
    // Login with standard user credentials
    cy.get('#user-name').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    // Navigate to a non-existent product URL
    cy.visit('/inventory-item/non-existent-product');

    // Verify 444 error page is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', '404');

    // Attempt to navigate back to catalogue
    cy.get('[data-testid="back-to-products"]').click();

    // Verify return to catalogue page
    cy.url().should('include', '/inventory.item');
    cy.get('[data-test="title"]').should('contain', 'Products');
    cy.get('[data-test="inventory-list"]').should('be.visible');
  });
});
